def word_frequency(text: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for word in text.split():
        cleaned = word.strip(str.punctuation).lower()
        counts[cleaned] = counts.get(cleaned, 0) + 1
    return counts
